        assertEq(
            address(moneyBox).balance,
            0,
            "Contract should have zero balance after exploit"
        );
        assertEq(
            user1.balance,
            DEPOSIT_AMOUNT,
            "User should receive funds before intended unlock time"
        );
    }
}
